fn element_wise_subtract(arr1: &Vec<i32>, arr2: &Vec<i32>) -> Vec<i32> {
    // The problem guarantees that `arr1` and `arr2` have the same length
    // and that each difference fits in an i32.
    debug_assert_eq!(arr1.len(), arr2.len());

    arr1.iter()
        .zip(arr2.iter())
        .map(|(a, b)| a - b)
        .collect()
}

